"""Final typography validation: selective baseline and evidence assembly."""
import hashlib
import json
import pathlib
import shutil
import subprocess
import sys
import re
import collections
import html
import csv

ROOT = pathlib.Path(__file__).resolve().parents[2]
OUT = ROOT / 'output/ui-update/fonts/FONT-10'

def write(path, obj):
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(obj, ensure_ascii=False, indent=2)+'\n', encoding='utf-8')

def git(*args):
    return subprocess.check_output(['git', *args], cwd=ROOT)

def baseline():
    OUT.mkdir(parents=True, exist_ok=True)
    assert not (OUT/'baseline.json').exists()
    paths = set(git('ls-files').decode().splitlines())
    for directory in ['Assets', 'docs', 'tools/ui', 'ProjectSettings', 'Packages']:
        paths.update(p.relative_to(ROOT).as_posix() for p in (ROOT/directory).rglob('*') if p.is_file() and '__pycache__' not in p.parts)
    paths.discard('tools/ui/font10_support.py')
    manifest = {}
    for name in sorted(paths):
        if '/orchestration/' in name or '/FONT-10/' in name: continue
        p = ROOT/name
        if not p.is_file(): continue
        manifest[name] = hashlib.sha256(p.read_bytes()).hexdigest()
        # Only editable source/configuration. Never recursively copy previous outputs.
        if name.startswith(('Assets/Editor/', 'Assets/Scripts/', 'docs/ui-update/', 'ProjectSettings/', 'Packages/')) or name == 'Assets/Scenes/GameScene.unity':
            dest = OUT/'baseline'/name
            dest.parent.mkdir(parents=True, exist_ok=True)
            shutil.copyfile(p,dest)
    write(OUT/'baseline.json', manifest)
    for name, args in [('initial-status.txt',('status','--short')),('initial-tracked.patch',('diff','--binary')),('initial-staged.patch',('diff','--cached','--binary'))]:
        (OUT/name).write_bytes(git(*args))
    print(json.dumps({'files':len(manifest),'HEAD':git('rev-parse','HEAD').decode().strip()}))

def player_fixture():
    source = (ROOT/'Assets/Editor/Tests/UI19NavigationValidation.cs').read_text(encoding='utf-8')
    source = source[:source.index('    /// <summary>Run with -executeMethod after removing')]+ '}\n'
    source = source.replace('using UnityEditor;\n', '')
    source = source.replace('UI19NavigationValidation', 'CampaignValidation')
    source = source.replace('EditorApplication.QueuePlayerLoopUpdate(); EditorWindow.GetWindow(typeof(Editor).Assembly.GetType("UnityEditor.GameView")).Repaint();', 'EditorApplication.QueuePlayerLoopUpdate();')
    source = source.replace('public static class CampaignValidation', 'namespace Font10PlayerQa\n{\npublic static class CampaignValidation') + '}\n'
    dest=ROOT/'Assets/Scripts/Game/Validation/Font10CampaignValidation.cs'
    dest.parent.mkdir(parents=True, exist_ok=True)
    dest.write_text('// Generated by tools/ui/font10_support.py player_fixture from the production UI-19 suite.\n// Assertions are preserved; only Editor scheduling, viewport and capture adapters change.\n#if DEVELOPMENT_BUILD || UNITY_EDITOR || FONT10_QA_PLAYER\n'+source+'#endif\n', encoding='utf-8')
    write(OUT/'player-fixture-provenance.json', {'source':'Assets/Editor/Tests/UI19NavigationValidation.cs','source_sha256':hashlib.sha256((ROOT/'Assets/Editor/Tests/UI19NavigationValidation.cs').read_bytes()).hexdigest(),'generated':dest.relative_to(ROOT).as_posix(),'generated_sha256':hashlib.sha256(dest.read_bytes()).hexdigest(),'assertions_preserved':True,'excluded':'Editor-only audit and batch Editor exit routines after RunSupplement.'})

def static_audit():
    assets=json.loads((ROOT/'docs/ui-update/font-assets.json').read_text(encoding='utf-8'))
    allowed={x['path'] for x in assets['assets']}
    guidmap={}
    for p in (ROOT/'Assets').rglob('*.meta'):
        if '/Examples & Extras/' in p.as_posix(): continue
        match=re.search(r'^guid: ([a-f0-9]+)$',p.read_text(encoding='utf-8',errors='replace'),re.M)
        if match: guidmap[match[1]]=p.relative_to(ROOT).as_posix()[:-5]
    font_guids={g:p for g,p in guidmap.items() if p.endswith('.asset') and (ROOT/p).is_file() and 'TMP_FontAsset' in (ROOT/p).read_text(encoding='utf-8',errors='ignore')[:1500]}
    # TMP font class serialization uses its script GUID, not necessarily the class name.
    for p in (ROOT/'Assets/TextMesh Pro').rglob('*.asset'):
        match=re.search(r'^guid: ([a-f0-9]+)$',p.with_suffix('.asset.meta').read_text(encoding='utf-8'),re.M) if p.with_suffix('.asset.meta').exists() else None
        if match and 'm_FaceInfo:' in p.read_text(encoding='utf-8',errors='ignore'):
            font_guids[match[1]]=p.relative_to(ROOT).as_posix()
    refs=[]
    for p in (ROOT/'Assets').rglob('*'):
        if not p.is_file() or p.suffix not in ['.unity','.prefab','.asset']:continue
        if 'Examples & Extras' in p.parts:continue
        name=p.relative_to(ROOT).as_posix();data=p.read_text(encoding='utf-8',errors='replace')
        for g in set(re.findall(r'guid: ([a-f0-9]{32})',data))&font_guids.keys():
            target=font_guids[g]
            if target in allowed:kind='production-face-or-finite-fallback'
            elif name=='Assets/Scenes/GameScene.unity':kind='legacy-production-reference'
            elif name.startswith('Assets/Scenes/'):kind='legacy-scene-outside-build'
            elif name.startswith('Assets/TextMesh Pro/'):kind='retained-TMP-settings-or-legacy-font'
            else:kind='review'
            refs.append({'asset':name,'guid':g,'font':target,'classification':kind})
    search=[]
    for directory in ['Assets/Scripts','Assets/Editor/UI']:
        for p in (ROOT/directory).rglob('*.cs'):
            for i,line in enumerate(p.read_text(encoding='utf-8',errors='replace').splitlines(),1):
                if re.search(r'Inter.?Tight|GetOSInstalledFontNames|CreateDynamicFontFromOSFont|Arial|LiberationSans|LegacyRuntime',line,re.I):search.append({'path':p.relative_to(ROOT).as_posix(),'line':i,'text':line.strip()})
    coverage=json.loads((ROOT/'docs/ui-update/font-coverage.json').read_text(encoding='utf-8'))
    refs=[r for r in refs if '/Sprite Assets/' not in r['font']]
    for row in refs:
        if row['asset'].startswith('Assets/_Recovery/'):
            row['classification']='recovered-editor-backup-outside-build'
        elif row['asset'].startswith('Assets/Layer Lab/'):
            row['classification']='third-party-scene-outside-build'
        elif row['classification']=='legacy-production-reference' or row['asset']=='Assets/Prefabs/Card_loan.prefab' and row['classification']=='review':
            row['classification']='residual-nested-prefab-font-override'
            row['note']='Old GUID retained in a serialized nested prefab property override. Exhaustive reopened scene/prefab TMP audit and actual Player observations resolve the current consumers to role-correct production faces. These references remain build dependencies; no primary legacy face was observed. Unrelated prefab overrides are preserved.'
    search=[r for r in search if not re.search(r'salarial|empresarial',r['text'],re.I)]
    write(OUT/'source-guid-audit.json',{'font_guids':font_guids,'references':refs,'source_matches':search,'classification_counts':dict(collections.Counter(r['classification'] for r in refs)),'inventory_rows':len(coverage['consumers']),'excluded_samples':'TMP Examples & Extras are third-party examples, outside production. Historical scenes remain outside the sole GameScene build entry.','illustration_exceptions':coverage['illustration_exceptions'],'reopened_consumer_evidence':'output/ui-update/fonts/FONT-10/saved-audit.json','os_font_api_match':'Font10PlayerValidation only lists installed names as a diagnostic; the production resolver does not call OS font creation or lookup.'})
    print(dict(collections.Counter(r['classification'] for r in refs)))

def source_hashes():
    sources=json.loads((ROOT/'docs/ui-update/font-sources.json').read_text(encoding='utf-8'))
    assets=json.loads((ROOT/'docs/ui-update/font-assets.json').read_text(encoding='utf-8'))
    rows=[]
    for row in sources['official_files']+sources['static_faces']+assets['fallback']['sources']+sources['font03_fallbacks']['static_faces']:
        p=ROOT/row['path']
        actual=hashlib.sha256(p.read_bytes()).hexdigest()
        rows.append({'path':row['path'],'bytes':p.stat().st_size,'sha256':actual,'expected':row['sha256'],'passed':actual==row['sha256']})
    metrics=[]
    for row in assets['assets']:
        data=(ROOT/row['path']).read_text(encoding='utf-8')
        match=re.search(r'  m_FaceInfo:\n(.*?)(?=\n  m_)',data,re.S)
        values={k:float(v) for k,v in re.findall(r'    (m_PointSize|m_Scale|m_LineHeight|m_AscentLine|m_DescentLine|m_CapLine|m_MeanLine): ([\d.\-]+)',match[1])}
        metrics.append({'path':row['path'],'face':row['name'],'native_line_height_em':values['m_LineHeight']/values['m_PointSize'],'metrics':values,'sha256':hashlib.sha256((ROOT/row['path']).read_bytes()).hexdigest()})
    write(OUT/'source-license-hashes.json',{'passed':all(r['passed'] for r in rows),'files':rows,'font_metrics':metrics})
    assert all(r['passed'] for r in rows)
    print({'verified':len(rows),'metrics':len(metrics)})


def comparisons():
    from PIL import Image, ImageOps, ImageDraw
    cases=[
        ('hub','01-hub.png',None,'completion-hub'),
        ('identification','02-abertura.png',(4,42,832,467),'completion-identification'),
        ('location','02-abertura.png',(841,42,1669,467),'completion-location'),
        ('restaurant','02-abertura.png',(4,514,832,918),'completion-restaurant'),
        ('menu','02-abertura.png',(841,514,1669,918),'completion-menu'),
        ('bank','03-gestao.png',(4,42,832,467),'completion-bank'),
        ('equipment','03-gestao.png',(841,42,1669,467),'completion-equipment'),
        ('team','03-gestao.png',(4,514,832,918),'completion-team'),
        ('establishment','03-gestao.png',(841,514,1669,918),'hub-establishment'),
        ('monthly','04-dre-mensal.png',None,'completion-month-3-summary'),
        ('quarterly','05-dre-trimestral.png',None,'completion-quarter'),
    ]
    rows=[]
    stable={'hub':'Panel_Menu','identification':'Panel_Identification','location':'Panel_Location','restaurant':'Panel_Restaurant','menu':'Panel_MenuPricing','bank':'Panel_Financial','equipment':'Panel_Equipment','team':'Panel_Team','establishment':'Panel_Establishment','monthly':'Panel_MonthlyResult','quarterly':'Panel_QuarterlyResult'}
    for name,concept,crop,capture in cases:
        source=ROOT/'art-source/references/concepts'/concept
        actual=OUT/'campaigns'/f'{capture}-1920x1080.png'
        state=OUT/'states'/f'{stable[name]}-normal-1920x1080.png'
        if state.exists() and name not in {'monthly','quarterly'}: actual=state
        if not actual.exists():continue
        reference=Image.open(source).convert('RGB')
        if crop:reference=reference.crop(crop)
        frame=Image.new('RGB',(1920,580),'#24113d')
        frame.paste(ImageOps.pad(reference,(960,540),color='#24113d'),(0,40))
        frame.paste(ImageOps.pad(Image.open(actual).convert('RGB'),(960,540),color='#24113d'),(960,40))
        draw=ImageDraw.Draw(frame);draw.text((16,13),f'{concept} / {name} - proportional reference fit',fill='white');draw.text((976,13),'FONT-10 / 1920x1080 / 50% design scale',fill='white')
        path=OUT/'comparisons'/f'{name}.jpg';path.parent.mkdir(parents=True,exist_ok=True);frame.save(path,quality=94)
        rows.append({'screen':name,'concept':source.relative_to(ROOT).as_posix(),'concept_crop_px':crop,'actual':actual.relative_to(ROOT).as_posix(),'comparison':path.relative_to(ROOT).as_posix(),'comparison_viewport_per_pane':[960,540],'method':'Actual 1920x1080 reduced uniformly 50%; reference contained proportionally in the same pane. Multi-screen annotations excluded with explicit crops; no stretch, font-only distortion or pixel identity claim.'})
    write(OUT/'concept-comparisons.json',rows)
    print(len(rows))

def gallery():
    captures=[]
    for filename,platform in [('capture-matrix.json','Editor'),('capture-matrix-stress.json','Editor stress'),('windows-player/capture-matrix.json','Windows Player')]:
        p=OUT/filename
        if not p.exists():continue
        for row in json.loads(p.read_text(encoding='utf-8')):
            path=pathlib.Path(row['path'])
            assert path.exists(),path
            row['path']=path.relative_to(ROOT).as_posix()
            captures.append({k:v for k,v in row.items() if k!='texts'}|{'suite':row.get('suite',path.parent.name),'platform':platform,'text_count':len(row['texts']),'overflow_count':sum(bool(t.get('isTextOverflowing')) and not t.get('input',False) for t in row['texts']),'sha256':hashlib.sha256(path.read_bytes()).hexdigest()})
    write(OUT/'capture-manifest.json',captures)
    with (OUT/'screen-resolution-state-matrix.csv').open('w',encoding='utf-8-sig',newline='') as f:
        fields=['platform','suite','name','width','height','state','frame','simulation','text_count','overflow_count','path','sha256']
        writer=csv.DictWriter(f,fieldnames=fields,extrasaction='ignore');writer.writeheader();writer.writerows(captures)
    comparisons()
    pairs=json.loads((OUT/'concept-comparisons.json').read_text(encoding='utf-8'))
    page=['<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FONT-10 · Validação final</title>',
          '<style>body{margin:0;background:#24113d;color:#f5f0e8;font:16px system-ui}main{max-width:1600px;margin:auto;padding:30px}h1{font-size:32px}a{color:#d6b6ff}nav,aside{padding:18px;background:#352147;border-radius:12px;margin:15px 0}select,input{font:inherit;padding:9px;margin:5px;background:#f5f0e8;color:#30243c;border:0;border-radius:5px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(420px,1fr));gap:18px}figure{margin:0;background:#352147;border-radius:8px;overflow:hidden}img{display:block;width:100%;height:auto}figcaption{padding:12px;font-size:14px}details{margin:16px 0}small{color:#cabbd8}</style><main>',
          '<h1>FONT-10 · Galeria global de tipografia</h1><p>18/10/2026 · Unity 6000.3.20f1 · Roboto / Roboto Condensed · faces reais, atlas estáticos e fallbacks finitos.</p>',
          '<aside>2340×1080 usa área segura simulada [90, 24, 2160, 1056] no Editor. As outras viewports são 1920×1080, 1366×768, 1280×720 e 1600×1000. Windows Player é execução real; Android físico não foi executado.</aside>',
          '<nav><a href="../../../docs/ui-update/qa/FONT-10.json">QA final</a> · <a href="FONT-10/screen-resolution-state-matrix.csv">Matriz CSV</a> · <a href="FONT-10/capture-manifest.json">Manifesto e hashes</a> · <a href="FONT-10/source-guid-audit.json">Auditoria de fontes/GUIDs</a> · <a href="FONT-10/build-windows.json">Build Windows</a> · <a href="FONT-10/windows-player/execution.json">Execução do Player</a> · <a href="FONT-10/build-android.json">Build Android</a></nav>',
          '<details><summary>Histórico FONT-01 a FONT-09, com datas e limites próprios</summary><nav>'+ ' · '.join(f'<a href="FONT-{i:02d}/index.html">FONT-{i:02d}</a>' for i in range(1,10))+'</nav></details>',
          '<details open><summary>Comparações com os cinco concepts</summary><p>Referência e tela real usam painéis 960×540. Redução proporcional uniforme; recortes dos concepts com várias telas estão declarados no JSON. As famílias são aproximações aprovadas, sem afirmação de identidade da fonte desenhada. Conteúdo econômico real, texto adicional, capitalização e artes existentes explicam diferenças de composição.</p><div class="grid">']
    if json.loads((OUT/'windows-player/process-exit.json').read_text(encoding='utf-8'))['exit_code']!=0:
        page.insert(3,'<aside style="border:2px solid #e8b95c"><strong>Ressalva de plataforma:</strong> fontes e campanhas passaram no Windows Player; o motor falha na limpeza nativa ao fechar (0xc0000005). O check de encerramento permanece falho e a homologação completa do Player é falsa. Android tem APK gerado, aviso de entrada Both e nenhum teste em aparelho. <a href="FONT-10/incident-recovery.json">Incidentes e limites</a>.</aside>')
