def preservation():
    before=json.loads((OUT/'baseline.json').read_text(encoding='utf-8'))
    own={'Assets/Editor/Tests/UI12EventValidation.cs','Assets/Editor/Tests/UI13MonthlyResultTests.cs','Assets/Editor/Tests/UI14QuarterlyResultTests.cs','Assets/Editor/Tests/UI18DialogTests.cs','docs/ui-update/font-contract.json','docs/ui-update/font-coverage.json','docs/ui-update/font-assets.json','docs/ui-update/visual-contract.json','docs/ui-update/tasks.json','docs/ui-update/COMECE-AQUI.txt','docs/art/tokens.json','docs/ui-update/font-tasks/README.md','docs/ui-update/font-tasks/FONT-10-validacao-final.md'}
    own.update({'Assets/Scripts/Game/Infrastructure/Database/DatabaseService.cs','Assets/Scripts/Game/Infrastructure/Session/PlayerSession.cs'})
    changed=[];missing=[];fonts=[]
    for name,digest in before.items():
        p=ROOT/name
        if not p.is_file():missing.append(name);continue
        actual=hashlib.sha256(p.read_bytes()).hexdigest()
        if actual!=digest:changed.append(name)
        if name.startswith('Assets/TextMesh Pro/') or name=='Assets/Resources/UI/ConceptFontSet.asset':fonts.append({'path':name,'baseline':digest,'current':actual,'unchanged':actual==digest})
    unexpected=[n for n in changed if n not in own]
    write(OUT/'baseline-preservation.json',{'passed':not unexpected and not missing,'files_checked':len(before),'changed_owned':changed,'unexpected_changes':unexpected,'missing':missing,'fonts_checked':len(fonts),'font_files_unchanged':all(f['unchanged'] for f in fonts),'font_files':fonts,'mutable_metadata_excluded':'output/ui-update/fonts/orchestration','new_recovery_files':'Assets/_Recovery and task recovery copies retained locally, excluded from commit.'})
    assert not unexpected and not missing,(unexpected,missing)
    assert all(f['unchanged'] for f in fonts)
    print({'checked':len(before),'changed_owned':len(changed),'fonts':len(fonts)})

def restore_build_newlines():
    """Undo only the build's verified line-ending rewrites, using entry hashes."""
    baseline=json.loads((OUT/'baseline.json').read_text(encoding='utf-8'))
    names=['Assets/Settings/UniversalRP.asset','Assets/UniversalRenderPipelineGlobalSettings.asset','ProjectSettings/GraphicsSettings.asset','ProjectSettings/ProjectSettings.asset','Assets/TextMesh Pro/Examples & Extras/Resources/Fonts & Materials/Roboto-Bold SDF.asset','Assets/Settings/Build Profiles/New Windows Profile.asset']
    rows=[]
    for name in names:
        p=ROOT/name;current=p.read_bytes();expected=baseline[name]
        copy=OUT/'baseline'/name
        source=copy.read_bytes() if copy.exists() else git('show','HEAD:'+name)
        variants=[source,source.replace(b'\r\n',b'\n'),source.replace(b'\r\n',b'\n').replace(b'\n',b'\r\n')]
        original=next((v for v in variants if hashlib.sha256(v).hexdigest()==expected),None)
        assert original is not None,('No verified entry bytes',name)
        assert current.replace(b'\r\n',b'\n')==original.replace(b'\r\n',b'\n'),('Not a newline-only build rewrite',name)
        rows.append({'path':name,'before_sha256':hashlib.sha256(current).hexdigest(),'restored_entry_sha256':expected,'newline_only':True})
        if current!=original:p.write_bytes(original)
    write(OUT/'build-newline-restoration.json',{'passed':True,'files':rows})
    print({'verified_newline_restorations':len(rows)})

def visual_review():
    load=lambda name:json.loads((OUT/name).read_text(encoding='utf-8'))
    pairs=load('concept-comparisons.json')
    assert len(pairs)==11 and len({p['concept'] for p in pairs})==5
    write(OUT/'visual-review.json',{'reviewed':True,'method':'Direct inspection of all eleven side-by-side images, six-face corpus sheet, wide signed money and long input start/end captures. Each comparison uses two 960x540 panes with proportional containment; explicit crops are recorded.','comparisons':pairs,'observations':{'families':'Roboto for body/major titles and Roboto Condensed for compact labels/actions preserve the accepted hierarchy with real face weights. The concepts use drawn letterforms; exact identity is not asserted.','apparent_size':'Production captions and table cells are smaller than the concept where the real catalog, financial columns and explanatory text are denser. Per-consumer sizes remain explicit; no global font shrink or text scaling was introduced in FONT-10.','spacing':'Native line height is retained. Dense catalogs/reports use native scroll; input clipping is accompanied by actual horizontal caret scrolling.','results':'Monthly and quarterly comparisons use populated, persisted campaigns rather than empty placeholders.','wide_values':'Signed seven-digit values fit the KPI and financial views in the five viewports. Descenders and accents remain visible at both ends of the long input.','remaining_composition_differences':'Existing artwork, step count, capitalization, catalog entries, economic values and content density differ from the concepts. These were preserved from the accepted working baseline.'}})
    print(dict(reviewed_comparisons=len(pairs)))

def final_notes():
    load=lambda name:json.loads((OUT/name).read_text(encoding='utf-8'))
    assert load('windows-player/process-exit.json')['exit_code'] in [0,3221225477]
    visual_review()
    logs={name:load(path) for name,path in [('native','console.json'),('stress','console-stress.json'),('windows','windows-player/console.json')]}
    summary={name:dict(collections.Counter(row['type'] for row in rows)) for name,rows in logs.items()}
    assert all(not any(row['type'] in ['Error','Exception','Assert'] for row in rows) for rows in logs.values())
    assert len(logs['native'])==5 and all(row['message']=='[EstablishmentSummaryController] Falha ao resetar o jogo: Constraint' for row in logs['native'])
