    assert not glyph_lines
    write(OUT/'console-audit.json',{'passed':True,'messages':summary,'native_expected_warnings':{'count':5,'reason':'One deliberate SQLite reset constraint failure per viewport; retry/cancel and preservation assertions passed.'},'player_missing_glyph_lines':glyph_lines,'windows_exit':load('windows-player/process-exit.json'),'shutdown':load('windows-player/shutdown.json'),'system_font_diagnostic':load('windows-player/font-assets.json')['systemFonts'],'unexpected_fallbacks':0,'scope':'Final accepted runs. Superseded fixture and lifecycle failures remain in incident-recovery.json and their original reports.'})
